//! Replays the operation trace produced by the old Go `bootstrapIPHealth` implementation.
//!
//! The fixture was generated by a temporary Go test that called `RecordResult` / `GetScore` with
//! a pinned `lastUpdatedAt`, then dumped the whole state plus the score after every step. The Rust
//! model has to land on the same numbers; float columns are compared with a 1e-9 relative
//! tolerance so a one-ULP `powf` difference on another libm does not fail the build.

use diting_bootstrap_core::Health;

const FIXTURE: &str = include_str!("fixtures/health_trace.tsv");

fn close(actual: f64, expected: f64, field: &str, step: usize) {
    let scale = actual.abs().max(expected.abs()).max(1.0);
    assert!(
        (actual - expected).abs() <= 1e-9 * scale,
        "step {step}: {field} = {actual}, expected {expected}"
    );
}

#[test]
fn the_health_trace_replays_exactly() {
    let mut health = Health::new(1_700_000_000_000_000_000);
    let mut rows = 0;

    for line in FIXTURE.lines().skip(1) {
        if line.trim().is_empty() {
            continue;
        }
        let fields: Vec<&str> = line.split('\t').collect();
        assert_eq!(fields.len(), 17, "row shape: {line}");
        let step: usize = fields[0].parse().unwrap();

        if fields[1] == "record" {
            let success = fields[2] == "true";
            let elapsed_ms: i64 = fields[3].parse().unwrap();
            let now_ns: i64 = fields[4].parse().unwrap();
            health.record_result(success, elapsed_ms, now_ns);
        }

        let now_ns: i64 = fields[4].parse().unwrap();
        let score = health.score(1.0, now_ns);
        let snapshot = health.snapshot();

        assert_eq!(
            snapshot.successes,
            fields[5].parse::<u64>().unwrap(),
            "step {step} successes"
        );
        assert_eq!(
            snapshot.failures,
            fields[6].parse::<u64>().unwrap(),
            "step {step} failures"
        );
        close(
            snapshot.ewma_ms,
            fields[7].parse().unwrap(),
            "ewma_ms",
            step,
        );
        close(
            snapshot.jitter_ms,
            fields[8].parse().unwrap(),
            "jitter_ms",
            step,
        );
        assert_eq!(
            snapshot.consecutive_failures,
            fields[9].parse::<u32>().unwrap(),
            "step {step} consecutive_failures"
        );
        assert_eq!(
            snapshot.cooldown_until_ns,
            fields[10].parse::<i64>().unwrap(),
            "step {step} cooldown_until_ns"
        );
        close(
            snapshot.decayed_successes,
            fields[11].parse().unwrap(),
            "decayed_successes",
            step,
        );
        close(
            snapshot.decayed_failures,
            fields[12].parse().unwrap(),
            "decayed_failures",
            step,
        );
        assert_eq!(
            snapshot.last_updated_ns,
            fields[13].parse::<i64>().unwrap(),
            "step {step} last_updated_ns"
        );

        close(score.weight, fields[14].parse().unwrap(), "weight", step);
        assert_eq!(
            score.cooling_down,
            fields[15] == "true",
            "step {step} cooling_down"
        );
        close(
            score.sample_count,
            fields[16].parse().unwrap(),
            "sample_count",
            step,
        );
        rows += 1;
    }

    assert_eq!(rows, 26, "the fixture is the 26-step trace");
}
